
import type { ReturnActor } from './ReturnActor.js';

export type ReturnDisposition = { /** RFC3339 timestamp. Format: date-time. */ "canceled_at"?: string; /** RFC3339 timestamp. Format: date-time. */ "created_at": string; "created_by": ReturnActor; "disposition_type": "sellable" | "quality_control" | "damaged" | "quarantined" | "repair" | "refurbish" | "liquidate" | "donate" | "discard" | "return_to_buyer" | "lost" | (string & {}); /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; /** Reason code for a failed merchandise disposition, when available. */ "failure_code"?: string; /** Explanation of a failed merchandise disposition, when available. */ "failure_message"?: string; "inventory_location_id"?: string; "inventory_movement_ids": Array<string>; "inventory_receipt_id"?: string; "metadata": Record<string, string>; /** RFC3339 timestamp. Format: date-time. */ "occurred_at": string; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "quantity": string; "reason": "inspection_result" | "return_policy" | "warehouse_override" | "safety_requirement" | "other" | (string & {}); "reason_message"?: string; "replaced_by_return_disposition_id"?: string; "replaces_return_disposition_id"?: string; "return_disposition_id": string; "return_id": string; "return_inspection_line_item_id"?: string; "return_line_item_id"?: string; "return_receipt_line_item_id"?: string; "status": "pending" | "succeeded" | "failed" | "canceled" | (string & {}); "supported_actions": Array<string>; /** RFC3339 timestamp. Format: date-time. */ "updated_at": string; /** Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "version": string; };
